//! Elastic Common Schema fields, for completion, hover, and type hints in
//! ES|QL, EQL, Kibana KQL, and Lucene.
//!
//! `catalogs/ecs/fields.json` is generated by `scripts/sync_ecs_fields.py`
//! from a tagged `elastic/ecs` release (Apache-2.0; see
//! `catalogs/ecs/NOTICE`). The list is never closed: elastic-1.0 says field
//! names MUST NOT be checked against one, so an unknown field is not a
//! diagnostic. Only a known field's type may drive a hint.

use serde::Deserialize;
use std::sync::OnceLock;

const FIELDS_JSON: &str = include_str!("../../../catalogs/ecs/fields.json");

#[derive(Debug, Clone, Deserialize)]
pub struct EcsField {
    pub name: String,
    #[serde(rename = "type")]
    pub type_name: String,
    pub level: String,
    pub short: String,
    #[serde(default)]
    pub array: bool,
    #[serde(default)]
    pub example: Option<String>,
    #[serde(default)]
    pub allowed: Vec<AllowedValue>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct AllowedValue {
    pub name: String,
    pub short: String,
}

#[derive(Deserialize)]
struct Catalog {
    source: String,
    tag: String,
    fields: Vec<EcsField>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| serde_json::from_str(FIELDS_JSON).expect("catalogs/ecs/fields.json"))
}

/// Every field, sorted by name.
pub fn fields() -> &'static [EcsField] {
    &catalog().fields
}

/// The ECS release the catalog was generated from, such as `v9.5.0`.
pub fn version() -> &'static str {
    let c = catalog();
    if c.tag.is_empty() { &c.source } else { &c.tag }
}

pub fn field(name: &str) -> Option<&'static EcsField> {
    let all = fields();
    all.binary_search_by(|f| f.name.as_str().cmp(name))
        .ok()
        .map(|i| &all[i])
}

/// Fields whose name starts with `prefix`.
pub fn with_prefix(prefix: &str) -> &'static [EcsField] {
    let all = fields();
    let start = all.partition_point(|f| f.name.as_str() < prefix);
    let end = start + all[start..].partition_point(|f| f.name.starts_with(prefix));
    &all[start..end]
}

/// Field-set roots (`process`, `event`, …) and top-level fields
/// (`@timestamp`, `message`), for completion before anything is typed.
pub fn roots() -> Vec<&'static str> {
    let mut out: Vec<&str> = fields()
        .iter()
        .map(|f| f.name.split('.').next().unwrap_or(&f.name))
        .collect();
    out.dedup();
    out
}

/// What a range comparison (`<`, `>=`, …) can mean for a field type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TypeClass {
    Numeric,
    Date,
    Ip,
    Text,
    Other,
}

impl EcsField {
    pub fn class(&self) -> TypeClass {
        match self.type_name.as_str() {
            "long" | "integer" | "short" | "byte" | "unsigned_long" | "double" | "float"
            | "half_float" | "scaled_float" => TypeClass::Numeric,
            "date" | "date_nanos" => TypeClass::Date,
            "ip" => TypeClass::Ip,
            "keyword" | "constant_keyword" | "wildcard" | "text" | "match_only_text" => {
                TypeClass::Text
            }
            _ => TypeClass::Other,
        }
    }

    /// Hover text: name, type, level, description, example, allowed values.
    pub fn markdown(&self) -> String {
        let array = if self.array { ", array" } else { "" };
        let mut md = format!(
            "**`{}`** · `{}`{array} · ECS {} ({})\n\n{}",
            self.name,
            self.type_name,
            self.level,
            version(),
            self.short
        );
        if let Some(example) = &self.example {
            md.push_str(&format!("\n\nExample: `{example}`"));
        }
        if !self.allowed.is_empty() {
            md.push_str("\n\nAllowed values:");
            for v in &self.allowed {
                md.push_str(&format!("\n- `{}`: {}", v.name, v.short));
            }
        }
        md
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_is_sorted_and_complete() {
        let all = fields();
        assert!(all.len() > 2000);
        assert!(all.windows(2).all(|w| w[0].name < w[1].name));
        let category = field("event.category").expect("event.category");
        assert_eq!(category.type_name, "keyword");
        assert!(category.allowed.iter().any(|v| v.name == "process"));
        assert!(field("process.command_line.text").is_some(), "multi-fields");
        assert!(field("no.such.field").is_none());
    }

    #[test]
    fn prefix_and_types() {
        assert!(
            with_prefix("process.parent.")
                .iter()
                .all(|f| f.name.starts_with("process.parent."))
        );
        assert!(!with_prefix("process.parent.").is_empty());
        assert_eq!(field("source.port").unwrap().class(), TypeClass::Numeric);
        assert_eq!(field("source.ip").unwrap().class(), TypeClass::Ip);
        assert_eq!(field("@timestamp").unwrap().class(), TypeClass::Date);
        assert!(roots().contains(&"process"));
        assert!(
            field("event.category")
                .unwrap()
                .markdown()
                .contains("Allowed values")
        );
    }
}
